        ->and(Artisan::call('azguard:audit:prune', ['--panel' => 'crm', '--before' => '2026-09-30T00:00:00Z']))->toBe(0)
        ->and(auditPruneMoments())->toBe(['2026-10-04', '2026-10-06']);
});

