function devToolsCommands(iterable $commands): array
{
    $ownership = Ownership::fromOracle();
    $owned = [];

    foreach ($commands as $command) {
        if ($ownership->referenceOwner('reference', $command::class) === 'devtools') {
            $owned[] = $command::class;
        }
    }
    sort($owned);

    return $owned;
}

