import json, subprocess
from pathlib import Path

def canon(obj):
    return json.dumps(obj, sort_keys=True, separators=(',', ':'), ensure_ascii=False)

drivers = ['sqlite','mysql','pgsql','mariadb']
for d in drivers:
    old = json.loads(subprocess.check_output(['git','show',f'304667bf:tests/Fixtures/Storage/ddl/{d}.json']))
    new = json.loads(Path(f'tests/Fixtures/Storage/ddl/{d}.json').read_text())
    audit = json.loads(Path(f'tests/Fixtures/Storage/ddl/{d}.audit.json').read_text())
    print(f'\n######## {d}')
    # old audit presence
    for mode, body in old.items():
        tables = list(body) if isinstance(body, dict) else type(body)
        has = isinstance(body, dict) and 'audit_log' in body
        print(f'  old mode {mode}: tables={list(body) if isinstance(body, dict) else body!r} audit={has}')
    print('  new core modes', {m: list(body) for m, body in new.items()})
    print('  new audit modes', {m: list(body) for m, body in audit.items()})
    # compare string audit_log
    old_al = old['string']['audit_log']
    new_al = audit['string']['audit_log']
    print('  string.audit_log equal', canon(old_al)==canon(new_al))
    if canon(old_al)!=canon(new_al):
        print('  OLD', canon(old_al)[:1500])
        print('  NEW', canon(new_al)[:1500])
    # other modes audit vs string
    for mode in old:
        if mode=='string':
            continue
        if isinstance(old[mode], dict) and 'audit_log' in old[mode]:
            same = canon(old[mode]['audit_log'])==canon(old_al)
            print(f'  old {mode}.audit_log == old string.audit_log? {same}')
            if not same:
                # show differing keys
                def flat(o, p=''):
                    if isinstance(o, dict):
                        for k,v in o.items():
                            yield from flat(v, p+'.'+str(k))
                    elif isinstance(o, list):
                        for i,v in enumerate(o):
                            yield from flat(v, p+f'[{i}]')
                    else:
                        yield p, o
                a=dict(flat(old_al)); b=dict(flat(old[mode]['audit_log']))
                diffs=[k for k in set(a)|set(b) if a.get(k)!=b.get(k)]
                print('    diff paths', diffs[:40])
    # core tables equality excluding audit_log
    for mode in old:
        ob = {k:v for k,v in old[mode].items() if k!='audit_log'}
        nb = new[mode]
        print(f'  core {mode} equal (audit stripped)', canon(ob)==canon(nb), 'old tables', sorted(ob), 'new', sorted(nb))
        if canon(ob)!=canon(nb):
            # which tables differ
            for t in sorted(set(ob)|set(nb)):
                if canon(ob.get(t))!=canon(nb.get(t)):
                    print('    DIFF table', t)
